const fs2 = require('fs-extra');
const path = require('path');
const get_parameters_js_1 = require('./environment');

function archiveReports(oldPath, newPath) {
    fs2.copy(oldPath, newPath, function (err) {
        if (err) {
            console.log('An error occured while copying the folder.');
            return console.error(err);
        }
        console.log('Archiving completed!');
    });
}

const { report_folder } = get_parameters_js_1.getParameters();
const reportFolder = report_folder || 'report';
const d = new Date();
const oldP = path.resolve(process.cwd(), `${reportFolder}/allure-report/`);
const newP = path.resolve(process.cwd(), `${reportFolder}/allure-archives/`, new Date(d.getTime() - (d.getTimezoneOffset() * 60000)).toISOString().split(".")[0].replace(/[T:]/g, '-'));
archiveReports(oldP, newP);
